package org.eclipse.kura.rest.wire.provider.test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.fail;

import java.util.Map;
import java.util.Optional;
import java.util.concurrent.TimeUnit;

import org.eclipse.kura.configuration.ComponentConfiguration;
import org.eclipse.kura.configuration.ConfigurationService;
import org.eclipse.kura.core.testutil.requesthandler.AbstractRequestHandlerTest;
import org.eclipse.kura.core.testutil.requesthandler.RestTransport;
import org.eclipse.kura.core.testutil.requesthandler.Transport.MethodSpec;
import org.eclipse.kura.core.testutil.service.ServiceUtil;
import org.eclipse.kura.crypto.CryptoService;
import org.junit.Test;
import org.osgi.service.useradmin.Group;
import org.osgi.service.useradmin.Role;
import org.osgi.service.useradmin.User;
import org.osgi.service.useradmin.UserAdmin;

import com.eclipsesource.json.Json;

/**
 * Feature: the Wires REST API only modifies existing components that are instances of the declared factory pid.
 */
public class UserStoreAccessTest extends AbstractRequestHandlerTest {

    private static final String USER_STORE_PID = "org.eclipse.kura.internal.useradmin.store.RoleRepositoryStoreImpl";
    private static final String DRIVER_FACTORY_PID = "org.eclipse.kura.util.test.driver.ChannelDescriptorTestDriver";

    private static final String WIRES_USER = "userStoreWiresOnly";
    private static final String WIRES_PASSWORD = "Wires-Passw0rd!";

    private Map<String, Object> userStorePropertiesBeforeRequest;

    public UserStoreAccessTest() {
        super(new RestTransport("wire/v1"));
    }

    /*
     * Scenarios
     */

    @Test
    public void updateRejectsFactoryPidNotMatchingExistingComponent() {
        givenIdentityWithPermissions(WIRES_USER, WIRES_PASSWORD, "rest.wires.admin");
        givenCurrentUserStoreConfiguration();

        whenUserStoreIsUpdatedDeclaringFactoryPid(DRIVER_FACTORY_PID, 4321L);

        thenRequestIsRejected();
        thenUserStoreWriteDelayIsUnchanged();
    }

    /*
     * Steps
     */

    /*
     * Given
     */

    private void givenIdentityWithPermissions(final String name, final String password, final String... permissions) {
        try {
            final UserAdmin userAdmin = ServiceUtil.trackService(UserAdmin.class, Optional.empty()).get(30,
                    TimeUnit.SECONDS);
            final CryptoService cryptoService = ServiceUtil.trackService(CryptoService.class, Optional.empty())
                    .get(30, TimeUnit.SECONDS);

            final User user = getOrCreateRole(userAdmin, "kura.user." + name, User.class);
            user.getCredentials().put("kura.password", cryptoService.sha256Hash(password));

            for (final String permission : permissions) {
                getOrCreateRole(userAdmin, "kura.permission." + permission, Group.class).addMember(user);
            }
        } catch (final Exception e) {
            fail("failed to create identity " + name + ": " + e.getMessage());
        }

        ((RestTransport) this.transport).setBasicCredentials(Optional.of(name + ":" + password));
    }

    private void givenCurrentUserStoreConfiguration() {
        this.userStorePropertiesBeforeRequest = getUserStoreProperties();
    }

    /*
     * When
     */

    private void whenUserStoreIsUpdatedDeclaringFactoryPid(final String factoryPid, final long writeDelay) {
        // the current users, roles and groups are sent back unchanged, only the write delay is modified
        whenRequestIsPerformed(new MethodSpec("PUT"), "/configs", "{\"configs\":[{\"pid\":\"" + USER_STORE_PID
                + "\",\"properties\":{" //
                + "\"service.factoryPid\":{\"type\":\"STRING\",\"value\":\"" + factoryPid + "\"}," //
                + stringProperty("users.config") + "," //
                + stringProperty("roles.config") + "," //
                + stringProperty("groups.config") + "," //
                + "\"write.delay.ms\":{\"type\":\"LONG\",\"value\":" + writeDelay + "}" //
                + "}}]}");
    }

    /*
     * Then
     */

    private void thenRequestIsRejected() {
        final int status = expectResponse().status;
        if (status / 100 == 2) {
            fail("expected the request to be rejected, but was " + status);
        }
    }

    private void thenUserStoreWriteDelayIsUnchanged() {
        assertEquals(this.userStorePropertiesBeforeRequest.get("write.delay.ms"),
                getUserStoreProperties().get("write.delay.ms"));
    }

    /*
     * Utilities
     */

    private static Map<String, Object> getComponentProperties(final String pid) {
        try {
            final ComponentConfiguration config = getConfigurationService().getComponentConfiguration(pid);
            assertNotNull(pid + " configuration not found", config);
            return config.getConfigurationProperties();
        } catch (final Exception e) {
            fail("failed to retrieve " + pid + " configuration: " + e.getMessage());
            throw new IllegalStateException("unreachable");
        }
    }

    private static ConfigurationService getConfigurationService() throws Exception {
        return ServiceUtil.trackService(ConfigurationService.class, Optional.empty()).get(30, TimeUnit.SECONDS);
    }

    private String stringProperty(final String name) {
        final Object value = this.userStorePropertiesBeforeRequest.get(name);
        return "\"" + name + "\":{\"type\":\"STRING\",\"value\":" + Json.value((String) value).toString() + "}";
    }

    private static Map<String, Object> getUserStoreProperties() {
        return getComponentProperties(USER_STORE_PID);
    }

    @SuppressWarnings("unchecked")
    private static <S extends Role> S getOrCreateRole(final UserAdmin userAdmin, final String name,
            final Class<S> classz) {
        final Role role = userAdmin.getRole(name);

        if (classz.isInstance(role)) {
            return (S) role;
        }

        final int type = classz == User.class ? Role.USER : Role.GROUP;
        return (S) userAdmin.createRole(name, type);
    }
}
